#!/usr/bin/env bash
# Evaluate independent frozen model fixtures through their retained jq oracle closure.
# Inputs: committed fixtures. Side effects: none; no daemon/AX/launchd access.
set -uo pipefail
ORACLE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)"
LEYLINE_PARCEL_DIR="$ORACLE_DIR"
FIXTURES_DIR="$ORACLE_DIR/fixtures"
JQ_LIB_FLAGS=(-L "$ORACLE_DIR/jq" -L "$ORACLE_DIR/arrange-optimizers")
SURFACES=(geometry project validate ops resolve reconcile_diff reconcile cursor autotile minsize floorplan f1 stacks balance arrangement atomgrid arrangement_valid arrangement_subsumption arrangement_targets lineops arrange arrange_optimize focusrole movemode overlap)
