actual_of() {
  local surface="$1" file="$2" flt rules_path
  flt="$(filter_for "$surface")" || return 1
  # A fixture may set "rules_path" to load a real shipped rules file into its
  # .rules (e.g. parcel/float-rules.json), so the data file's OWN content is
  # pinned by the test rather than a hand-copied echo that can silently drift.
  # Resolved relative to $LEYLINE_PARCEL_DIR; the normal filter still reads .rules.
  rules_path="$(jq -r '.rules_path // empty' "$file" 2>/dev/null)"
  if [[ -n "$rules_path" ]]; then
    jq --slurpfile rf "$LEYLINE_PARCEL_DIR/$rules_path" '.rules = $rf[0]' "$file" \
      | jq "${JQ_LIB_FLAGS[@]}" -c "$flt" | jq -S .
  else
    jq "${JQ_LIB_FLAGS[@]}" -c "$flt" "$file" | jq -S .
  fi
}

run_fixture() {
  local surface="$1" name="$2"
  local file="$FIXTURES_DIR/$surface/${name}.json"
  if [[ ! -f "$file" ]]; then
    printf '✗ %s/%s: missing fixture\n' "$surface" "$name"; return 1
  fi
  if ! jq -e 'has("expect")' "$file" >/dev/null 2>&1; then
    printf '? %s/%s: no expect oracle (run regenerate, then review)\n' "$surface" "$name"; return 2
  fi
  local actual expected
  actual="$(actual_of "$surface" "$file")" || {
    printf '✗ %s/%s: filter failed\n' "$surface" "$name"; return 1
  }
  expected="$(jq -S '.expect' "$file")"
  if [[ "$actual" == "$expected" ]]; then
    printf '✓ %s/%s\n' "$surface" "$name"; return 0
  fi
  printf '✗ %s/%s: output diverges\n' "$surface" "$name"
  diff <(printf '%s\n' "$expected") <(printf '%s\n' "$actual") | head -60
  return 1
}


# Reuse the canonical fixture filter table without rerunning its corpus.
if [[ "${BASH_SOURCE[0]}" != "$0" ]]; then return 0; fi

checks=0 failures=0
for surface in "${SURFACES[@]}"; do
  count=0
  for fixture in "$FIXTURES_DIR/$surface/"*.json; do
    [[ -f "$fixture" ]] || continue
    count=$((count+1)); checks=$((checks+1))
    run_fixture "$surface" "$(basename "$fixture" .json)" || failures=$((failures+1))
  done
  if (( count == 0 )); then printf 'not ok %s/empty-fixture-corpus\n' "$surface"; failures=$((failures+1)); fi
done
printf 'frozen-models: %s checks, %s failures\n' "$checks" "$failures"
[[ "$checks" -gt 0 && "$failures" == 0 ]]
